    public static func read(from buffer: inout WireBuffer) throws(WireError) -> BitmapFontData {
        let id = try buffer.readInt()
        let raw_versionAndNumGlyphs = try buffer.readInt()
        let numGlyphs = Int32((UInt32(bitPattern: raw_versionAndNumGlyphs) >> BitLayout.versionAndNumGlyphsNumGlyphsShift) & BitLayout.versionAndNumGlyphsNumGlyphsMask)
        let version = (Int32(bitPattern: UInt32(bitPattern: raw_versionAndNumGlyphs) << BitLayout.versionAndNumGlyphsVersionLeftShift) >> BitLayout.versionAndNumGlyphsVersionRightShift)
        let _glyphsCount = Int(numGlyphs)
        guard _glyphsCount >= 0 else {
            throw WireError.invalidLength(type: "BitmapFontData", field: "glyphs", length: _glyphsCount)
        }
        guard _glyphsCount <= buffer.remaining / Glyph.minWireBytes else {
            throw WireError.lengthExceedsBuffer(type: "BitmapFontData", field: "glyphs", length: _glyphsCount)
        }
        var glyphs = [Glyph]()
        glyphs.reserveCapacity(Swift.min(_glyphsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_glyphsCount {
            glyphs.append(try Glyph.read(from: &buffer))
        }
        let kerningTable: [KerningPair]
        if Int(version) >= WireExpressionConstants.bitmapFontVersionKerning {
            let _kerningTableCount = Int(UInt16(bitPattern: try buffer.readShort()))
            guard _kerningTableCount >= 0 else {
                throw WireError.invalidLength(type: "BitmapFontData", field: "kerningTable", length: _kerningTableCount)
            }
            guard _kerningTableCount <= buffer.remaining / KerningPair.minWireBytes else {
                throw WireError.lengthExceedsBuffer(type: "BitmapFontData", field: "kerningTable", length: _kerningTableCount)
            }
            var kerningTableTmp = [KerningPair]()
            kerningTableTmp.reserveCapacity(Swift.min(_kerningTableCount, WireLimits.maxInitialCapacity))
            for _ in 0..<_kerningTableCount {
                kerningTableTmp.append(try KerningPair.read(from: &buffer))
            }
            kerningTable = kerningTableTmp
        } else {
            kerningTable = []
        }
        return BitmapFontData(id: id, glyphs: glyphs, kerningTable: kerningTable)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(opCode.rawValue)
        buffer.writeInt(id)
        let numGlyphs: Int32 = Int32(glyphs.count)
        let version: Int32 = (!kerningTable.isEmpty ? 1 : 0)
        buffer.writeInt(Int32(bitPattern: ((UInt32(bitPattern: Int32(numGlyphs)) & BitLayout.versionAndNumGlyphsNumGlyphsMask) << BitLayout.versionAndNumGlyphsNumGlyphsShift) | ((UInt32(bitPattern: Int32(version)) & BitLayout.versionAndNumGlyphsVersionMask) << BitLayout.versionAndNumGlyphsVersionShift)))
