    ///   - expressionX: X/radius RPN expression
    ///   - expressionY: Y/angle RPN expression (may be empty)
    public init(id: Int32 = 0, flags: Int32 = 0, min: Float = 0.0, max: Float = 0.0, count: Float = 0.0, expressionX: [Float] = [], expressionY: [Float] = []) {
        self.id = id
        self.flags = flags
