        }
        guard _expressionXCount <= WireLimits.maxExpressionSize else {
            throw WireError.lengthExceedsLimit(type: "PathExpression", field: "expressionX", length: _expressionXCount, limit: WireLimits.maxExpressionSize)
        }
        guard _expressionXCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            throw WireError.lengthExceedsBuffer(type: "PathExpression", field: "expressionX", length: _expressionXCount)
        }
        var expressionX = [Float]()
