    public init(id: Int32 = 0, leftVolume: Float = 0.0, rightVolume: Float = 0.0, rate: Float = 0.0, params: [Float] = []) {
        self.id = id
        self.leftVolume = leftVolume
        self.rightVolume = rightVolume
        self.rate = rate
        self.params = params
    }

