    public static func read(from buffer: inout WireBuffer) throws(WireError) -> SoundExpression {
        let id = try buffer.readInt()
        let leftVolume = try buffer.readFloat()
        let rightVolume = try buffer.readFloat()
        let rate = try buffer.readFloat()
        let _paramsCount = Int(try buffer.readInt())
