            throw WireError.invalidLength(type: "SoundExpression", field: "params", length: _paramsCount)
        }
        guard _paramsCount <= WireLimits.soundExpressionParamsMaxLength else {
            throw WireError.lengthExceedsLimit(type: "SoundExpression", field: "params", length: _paramsCount, limit: WireLimits.soundExpressionParamsMaxLength)
        }
        guard _paramsCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            throw WireError.lengthExceedsBuffer(type: "SoundExpression", field: "params", length: _paramsCount)
        }
        var params = [Float]()
        params.reserveCapacity(Swift.min(_paramsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_paramsCount {
