        case .widthInModifierOperation:
            return .widthInModifierOperation(try WidthInModifierOperation.read(from: &buffer))
        case .heightInModifierOperation:
            return .heightInModifierOperation(try HeightInModifierOperation.read(from: &buffer))
        case .collapsibleColumn:
            return .collapsibleColumn(try CollapsibleColumn.read(from: &buffer))
        case .imageLayout:
            return .imageLayout(try ImageLayout.read(from: &buffer))
        case .collapsiblePriorityModifierOperation:
            return .collapsiblePriorityModifierOperation(try CollapsiblePriorityModifierOperation.read(from: &buffer))
        case .runAction:
            return .runAction(try RunAction.read(from: &buffer))
        case .alignByModifierOperation:
            return .alignByModifierOperation(try AlignByModifierOperation.read(from: &buffer))
        case .layoutCompute:
            return .layoutCompute(try LayoutCompute.read(from: &buffer))
        case .coreText:
            return .coreText(try CoreText.read(from: &buffer))
        case .flowLayout:
            return .flowLayout(try FlowLayout.read(from: &buffer))
        case .skip:
            return .skip(evaluateSkip ? try Skip.readForPlayer(from: &buffer, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles) : try Skip.read(from: &buffer))
        case .textStyle:
            return .textStyle(try TextStyle.read(from: &buffer))
        case .dimensionConstraintsModifierOperation:
            return .dimensionConstraintsModifierOperation(try DimensionConstraintsModifierOperation.read(from: &buffer))
        case .patternForEach:
            return .patternForEach(try PatternForEach.read(from: &buffer))
        case .includeReferencedOperations:
            return .includeReferencedOperations(try IncludeReferencedOperations.read(from: &buffer))
        case .patternDefine:
            return .patternDefine(try PatternDefine.read(from: &buffer))
        case .patternInflation:
            return .patternInflation(try PatternInflation.read(from: &buffer))
        case .patternArgument:
            return .patternArgument(try PatternArgument.read(from: &buffer))
        case .patternBlock:
            return .patternBlock(try PatternBlock.read(from: &buffer))
        case .coreSemantics:
            return .coreSemantics(try CoreSemantics.read(from: &buffer))
        }
    }
}

/// A Remote Compose document: its header and its operations.
public struct WireDocument: Sendable, Hashable {
    public static let maxHeaderProperties: Int = 1000
    public static let maxOperationCount: Int = 100_000

    public var majorVersion: Int32
    public var minorVersion: Int32
    public var patchVersion: Int32
    /// A modern header's properties, in the order read and written; nil for a legacy header.
    public var properties: [HeaderProperty]?
    /// The document's size: a legacy header's fields, or a modern header's size properties.
    public var width: Int32
    public var height: Int32
    /// The profile bits: a legacy header's field, or a modern header's profiles property.
    public var capabilities: Int64
    public var operations: [WireOperation]

    public init(majorVersion: Int32 = HeaderConstants.majorVersion, minorVersion: Int32 = HeaderConstants.minorVersion, patchVersion: Int32 = HeaderConstants.patchVersion, properties: [HeaderProperty]? = nil, width: Int32 = HeaderLayout.defaultSize, height: Int32 = HeaderLayout.defaultSize, capabilities: Int64 = 0, operations: [WireOperation] = []) {
        self.majorVersion = majorVersion
        self.minorVersion = minorVersion
        self.patchVersion = patchVersion
        self.properties = properties
        self.width = width
        self.height = height
        self.capabilities = capabilities
        self.operations = operations
    }

    /// Reads a document from its bytes.
    public static func load(from bytes: [UInt8], maxOperations: Int = maxOperationCount) throws(WireError) -> WireDocument {
        return try loadImpl(from: bytes, maxOperations: maxOperations, evaluateSkip: false, playerApiLevel: 0, playerProfiles: 0)
    }

    /// Reads a document, evaluating its conditional skips against the target player.
    public static func loadForPlayer(from bytes: [UInt8], playerApiLevel: Int32, playerProfiles: Int32 = 0, maxOperations: Int = maxOperationCount) throws(WireError) -> WireDocument {
        return try loadImpl(from: bytes, maxOperations: maxOperations, evaluateSkip: true, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles)
    }

    private static func loadImpl(from bytes: [UInt8], maxOperations: Int, evaluateSkip: Bool, playerApiLevel: Int32, playerProfiles: Int32) throws(WireError) -> WireDocument {
        var buffer = WireBuffer(data: bytes)
        var doc = WireDocument()
        guard buffer.available else { return doc }
        guard try buffer.readByte() == OpCode.header.rawValue else {
            throw WireError.expectedHeader
        }
        let rawMajor = try buffer.readInt()
        doc.minorVersion = try buffer.readInt()
        doc.patchVersion = try buffer.readInt()
        if (UInt32(bitPattern: rawMajor) & HeaderLayout.magicMask) == UInt32(bitPattern: HeaderConstants.magicNumber) {
            doc.majorVersion = rawMajor & HeaderLayout.versionMask
            let numProps = Int(try buffer.readInt())
            guard numProps >= 0 && numProps <= maxHeaderProperties else {
                throw WireError.invalidLength(type: "Header", field: "properties", length: numProps)
            }
            guard numProps <= buffer.remaining / HeaderProperty.minWireBytes else {
                throw WireError.lengthExceedsBuffer(type: "Header", field: "properties", length: numProps)
            }
            var properties: [HeaderProperty] = []
            properties.reserveCapacity(numProps)
            for _ in 0..<numProps {
                let property = try HeaderProperty.read(from: &buffer)
                let key = Int32(property.tag) & HeaderLayout.propertyKeyMask
                let value = property.intValue.map(Int64.init) ?? property.longValue
                if key == HeaderProperty.compress, let value, value != 0 {
                    throw WireError.compressedDocument
                }
                if key == HeaderProperty.docWidth, let width = property.intValue { doc.width = width }
                if key == HeaderProperty.docHeight, let height = property.intValue { doc.height = height }
                if key == HeaderProperty.docProfiles, let value { doc.capabilities = property.intValue.map { Int64(UInt32(bitPattern: $0)) } ?? value }
                properties.append(property)
            }
            doc.properties = properties
        } else if rawMajor >= 0 && rawMajor <= HeaderLayout.versionMask {
            doc.majorVersion = rawMajor
            doc.width = try buffer.readInt()
            doc.height = try buffer.readInt()
            doc.capabilities = try buffer.readLong()
        } else {
            throw WireError.invalidHeaderMagic(rawMajor)
        }

        while buffer.available {
            guard doc.operations.count < maxOperations else {
                throw WireError.operationLimitExceeded(maxOperations)
            }
            let opByte = try buffer.readByte()
            guard let opCode = OpCode(rawValue: opByte) else {
                throw WireError.unknownOpcode(opByte)
            }
            doc.operations.append(try WireOperation.read(opCode, from: &buffer, evaluateSkip: evaluateSkip, playerApiLevel: playerApiLevel, playerProfiles: playerProfiles))
        }
        return doc
    }

    /// The document's bytes: the header as it was read (modern with its properties, or
    /// legacy), then every operation.
    public func save() throws(WireError) -> [UInt8] {
        var buffer = WireBuffer()
        buffer.writeByte(OpCode.header.rawValue)
        if let properties {
            buffer.writeInt(HeaderConstants.magicNumber | (majorVersion & HeaderLayout.versionMask))
            buffer.writeInt(minorVersion)
            buffer.writeInt(patchVersion)
            buffer.writeInt(Int32(properties.count))
            for property in properties { try property.write(to: &buffer) }
        } else {
            buffer.writeInt(majorVersion)
            buffer.writeInt(minorVersion)
            buffer.writeInt(patchVersion)
            buffer.writeInt(width)
            buffer.writeInt(height)
            buffer.writeLong(capabilities)
        }
        for operation in operations {
            try operation.write(to: &buffer)
        }
        return buffer.data
    }
}
